<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoAfp, guardarAfp, listarAfps } from '../services/afps'
import type { Afp, AfpPayload } from '../interfaces/afps.interface'

const rows=ref<Afp[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const defaults:AfpPayload={codigo:'',nombre:'',comision_porcentaje:0,prima_seguro:0}
const form=reactive<AfpPayload>({...defaults})
const message=(value:unknown)=>value instanceof Error?value.message:'No se pudo completar la operación.'

async function load(next=1){loading.value=true;error.value='';try{const result=await listarAfps(criterio.value,next);rows.value=result.data;page.value=result.current_page;lastPage.value=result.last_page;total.value=result.total}catch(value){error.value=message(value)}finally{loading.value=false}}
function open(item?:Afp){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,nombre:item.nombre,comision_porcentaje:Number(item.comision_porcentaje),prima_seguro:Number(item.prima_seguro)}:{...defaults});error.value='';modal.value=true}
function validPercentage(value:number){return Number.isFinite(value)&&value>=0&&value<=100}
function validate(){if(form.codigo.trim().length<2)return 'El código debe tener al menos 2 caracteres.';if(form.codigo.trim().length>10)return 'El código admite como máximo 10 caracteres.';if(form.nombre.trim().length<3)return 'El nombre debe tener al menos 3 caracteres.';if(form.nombre.trim().length>150)return 'El nombre admite como máximo 150 caracteres.';if(!validPercentage(form.comision_porcentaje))return 'La comisión debe ser un número entre 0 y 100.';if(!validPercentage(form.prima_seguro))return 'La prima de seguro debe ser un número entre 0 y 100.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarAfp(editing.value,{...form,codigo:form.codigo.trim().toUpperCase(),nombre:form.nombre.trim().toUpperCase()});modal.value=false;success.value=`AFP ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(value){error.value=message(value)}finally{saving.value=false}}
async function toggle(item:Afp){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} la AFP ${item.nombre}?`))return;try{const result=await cambiarEstadoAfp(item.id);item.estado=result.estado;success.value=result.message??`AFP ${item.estado?'activada':'desactivada'} correctamente.`}catch(value){error.value=message(value)}}
function clearFilters(){criterio.value='';load(1)}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / AFP</nav><header class="hero"><div class="mark">AFP</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Administradoras de fondos de pensiones</h1><p>Comisiones y primas de seguro aplicables a los aportes previsionales.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nueva AFP</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por código o nombre<input v-model.trim="criterio" placeholder="Ej. INTEGRA o PRIMA"></label><button>Buscar</button><button type="button" class="soft" @click="clearFilters">Limpiar</button></form><section class="table-card"><header><div><small>SISTEMA PREVISIONAL</small><h2>AFP registradas</h2></div></header><div v-if="loading" class="empty">Consultando AFP…</div><div v-else-if="!rows.length" class="empty">No se encontraron AFP.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Nombre</th><th>Comisión</th><th>Prima de seguro</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td><span class="percentage commission">{{Number(item.comision_porcentaje).toFixed(2)}}%</span></td><td><span class="percentage insurance">{{Number(item.prima_seguro).toFixed(2)}}%</span></td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">AFP</div><div><small>SISTEMA PREVISIONAL</small><h2>{{editing?'Editar':'Registrar'}} AFP</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Nombre *<input v-model="form.nombre" maxlength="150" @input="form.nombre=form.nombre.toUpperCase()"></label><label>Comisión (%) *<input v-model.number="form.comision_porcentaje" type="number" min="0" max="100" step="0.01"><small>Porcentaje entre 0.00 y 100.00.</small></label><label>Prima de seguro (%) *<input v-model.number="form.prima_seguro" type="number" min="0" max="100" step="0.01"><small>Porcentaje entre 0.00 y 100.00.</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#23818c;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.58rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#e8f7f8;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(500px,100%);font-size:.52rem}.filters input,.dialog input{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:800px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive,.percentage{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.commission{color:#196b74;background:#e4f5f7}.insurance{color:#89600d;background:#fff1d0}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(650px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.dialog label small{margin-top:5px;color:#7e8a90;font-weight:400}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
